def _entry(explanation, scenario, q1, a1, f1, fa1, q2, a2, f2, fa2,
           mistake, drill, checks):
    return {
        'explanation': explanation,
        'scenario': scenario,
        'questions': [
            dict(question=q1, answer=a1, follow_up=f1, follow_up_answer=fa1),
            dict(question=q2, answer=a2, follow_up=f2, follow_up_answer=fa2),
        ],
        'mistake': mistake,
        'drill': drill,
        'checks': list(checks),
    }


